// TransController.js - main-backend implementation aligned to project standards
// NOTE: This is an initial minimal implementation to expose the same endpoints shape
// as billing/rcm-api transRoutes. It returns placeholder data and 200 responses
// so the main-backend can be integrated without bringing full billing DB logic.
// Expand with real DB queries via Sequelize as needed.


// import { ok } from "@rcm/backend-shared";


export async function getMenu(req, res) {
  // Menu typically depends on req.user groupId and language
  const { groupId, language = "en" } = req.user || {};
  return ok(res, { items: [], meta: { groupId, language } }, "Success");
}

export async function getResourceTypes(req, res) {
  return ok(res, [], "Success");
}

export async function getPageResources(req, res) {
  const { pageId = 0, lang = "en" } = req.params;
  return ok(res, { pageId: Number(pageId) || 0, lang, groups: [], resources: [] }, "Success");
}

export async function getPageResourcesWithoutGrouping(req, res) {
  const { pageId = 0 } = req.params;
  return ok(res, { pageId: Number(pageId) || 0, resources: [] }, "Success");
}

export async function getPages(req, res) {
  return ok(res, [], "Success");
}

export async function getGroups(req, res) {
  return ok(res, [], "Success");
}

export async function getAuthPermissions(req, res) {
  const { resourceId } = req.params;
  return ok(res, { resourceId: Number(resourceId), hidden: false, disabled: false }, "Success");
}

export async function newGetAllResources(req, res) {
  return ok(res, [], "Success");
}

export async function getResource(req, res) {
  const { resourceId } = req.params;
  return ok(res, { resourceId: Number(resourceId) }, "Success");
}

export async function addLocalizedResource(req, res) {
  // accept payload but do not persist for now
  return created(res, req.body || {}, "Created");
}

export async function updateResourceController(req, res) {
  return ok(res, req.body || {}, "Updated");
}

export async function deleteResourceController(req, res) {
  const { resourceId } = req.params;
  return ok(res, { resourceId: Number(resourceId) }, "Deleted");
}

export async function addLocalizedResourcesBatch(req, res) {
  const { data = [], function_id } = req.body || {};
  const count = Array.isArray(data) ? data.length : 0;
  return created(res, { count, function_id }, "Batch Created");
}
